mod solution;

fn main() {
    let cases = [
    (r#"[1,2,3]"#, r#"1,2;1,3;2,3"#),
    (r#"[1,2]"#, r#"1,2"#),
    (r#"
[1,2]
"#, r#"1,2"#),
    (r#"  
[1,2,3]
  "#, r#"1,2;1,3;2,3"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS combinations");
}
